from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(amt="100.00", status="captured"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# rounding
p=mk(); process_refund_request(p,"49.999","u",T0); print("round",p.refunded_amount)
# full refund
p=mk(); process_refund_request(p,"100.00","u",T0); print("full",p.refunded_amount,p.status)
# over refund
p=mk(); process_refund_request(p,"60.00","u",T0)
try: process_refund_request(p,"50.00","u",T0)
except BillingError as e: print("over",e.code)
# non captured
try: process_refund_request(mk(status="authorized"),"1.00","u",T0)
except BillingError as e: print("state",e.code)
# non positive
try: process_refund_request(mk(),"0","u",T0)
except BillingError as e: print("nonpos",e.code)
# approval
try: process_refund_request(mk("1000.00"),"500.01","u",T0)
except BillingError as e: print("approval",e.code)
p=mk("1000.00"); process_refund_request(p,"500.01","u",T0,approved_by="boss"); print("approved",p.refunded_amount)
# idempotency
p=mk(); process_refund_request(p,"10.00","u",T0,idempotency_key="k1")
process_refund_request(p,"10.00","u",T0,idempotency_key="k1"); print("idem",p.refunded_amount, len(audit.events("payment_refunded")))
EOF"}

